"use client";
import React, { useState } from "react";
import { fetchSpringApi } from "./springApiCalls";

export default function Home() {
  const [apiResult, setApiResult] = useState("");
  const [loading, setLoading] = useState(false);

  const handleClick = async () => {
    setLoading(true);
    setApiResult("");

    try {
      const result = await fetchSpringApi();
      setApiResult(result);
    } catch (e) {
      const message = e instanceof Error ? e.message : "Unknown error";
      setApiResult(`Error: ${message}`);
    } finally {
      setLoading(false);
    }
  };

  return (
    <main
      style={{
        minHeight: "100vh",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "flex-start",
        padding: "72px 28px 28px",
        color: "#172033",
      }}
    >
      <h1
        style={{
          margin: 0,
          textAlign: "center",
          maxWidth: 900,
          fontSize: "clamp(1.75rem, 1.4vw, 2.6rem)",
          lineHeight: 1.2,
          letterSpacing: "-0.02em",
          fontFamily: '"Avenir Next", "Segoe UI", sans-serif',
        }}
      >
        Welcome to NEXUS API Studio
      </h1>

      <p
        style={{
          marginTop: 14,
          marginBottom: 0,
          textAlign: "center",
          maxWidth: 860,
          fontSize: "clamp(1rem, 1.5vw, 1.15rem)",
          lineHeight: 1.65,
          color: "#2b3a55",
          fontFamily: '"Avenir Next", "Segoe UI", sans-serif',
        }}
      >
        TIP-powered API testing platform built by the TIE Team. A unified workspace
        for designing, testing, and debugging APIs with speed and precision.
      </p>

      <p
        style={{
          marginTop: 14,
          marginBottom: 0,
          textAlign: "center",
          maxWidth: 820,
          fontSize: "0.95rem",
          lineHeight: 1.6,
          color: "#51617d",
          background: "#eef4ff",
          border: "1px solid #d9e5ff",
          borderRadius: 10,
          padding: "10px 12px",
          fontFamily: '"Avenir Next", "Segoe UI", sans-serif',
        }}
      >
        Usage Notice: Use one workspace per team to keep setups minimal.
      </p>

      <button
        type="button"
        onClick={handleClick}
        disabled={loading}
        style={{ marginTop: 24, padding: "8px 16px", fontSize: 16 }}
      >
        {loading ? "Calling Spring Boot API..." : "Call Spring Boot API"}
      </button>

      {apiResult && (
        <div
          style={{
            marginTop: 16,
            padding: 12,
            border: "1px solid #c7d3e7",
            borderRadius: 8,
            background: "#f7faff",
            color: "#1f2a44",
            fontFamily: '"Avenir Next", "Segoe UI", sans-serif',
          }}
        >
          {apiResult}
        </div>
      )}
    </main>
  );
}
